	const MSO_LIST_LEVEL = /mso-list\s*:[^;"']*?\blevel(\d+)/i;
	const MARGIN_LEFT_DECLARATION = /(?:^|;)\s*margin-left\s*:\s*([^;]+)/i;
	const CSS_LENGTH = /^\s*(-?\d*\.?\d+)\s*([a-z]*)\s*$/i;
